/// The client side of `Interop`, over one Bead client: a requester of each procedure its server answers, by its name.
#[derive(Debug, Clone)]
pub struct InteropClient {
    procedures: &'static InteropProcedures,
    service: ::bead::ServiceClient,
    request: InteropRequesters,
    notifications: InteropNotifications,
}

impl InteropClient {
    /// The client side of `Interop`, over `client`, given its options: whether it validates, and the windows of its notifications.
    ///
    /// # Errors
    ///
    /// A [`ProgrammerError`](::bead::ProgrammerError) where the runtime refuses the service; for a window of 0, a second client side over one client at another window, or a procedure its router refuses to declare.
    pub fn new(client: &::bead::Client, options: &InteropClientOptions) -> Result<Self, ::bead::ProgrammerError> {
        let procedures = InteropProcedures::get()?;
        let mut layer = ::bead::ServiceClientOptions::default();

        let windows = options.windows.clone().unwrap_or_default();
        let mut given = ::std::collections::BTreeMap::new();

        if let Some(window) = windows.ticks {
            given.insert("ticks".to_owned(), window);
        }

        layer.windows = Some(given);
        layer.fail_fast = options.fail_fast;
        layer.validates = options.validates;

        let service = ::bead::ServiceClient::new(procedures.all(), client, &layer)?;
        let request = InteropRequesters {
            echo: service.requester_of(&procedures.echo)?,
            fail: service.requester_of(&procedures.fail)?,
            slow: service.requester_of(&procedures.slow)?,
            cancellations: service.requester_of(&procedures.cancellations)?,
            denied: service.requester_of(&procedures.denied)?,
            broken: service.requester_of(&procedures.broken)?,
            bytes: service.requester_of(&procedures.bytes)?,
            ask: service.requester_of(&procedures.ask)?,
            ticks: service.requester_of(procedures.ticks.descriptor())?,
            tick: service.requester_of(&procedures.tick)?,
            login: service.requester_of(&procedures.login)?,
            logout: service.requester_of(&procedures.logout)?,
            whoami: service.requester_of(&procedures.whoami)?,
            register: service.requester_of(&procedures.register)?,
            unregister: service.requester_of(&procedures.unregister)?,
            end_session: service.requester_of(&procedures.end_session)?,
            end_sessions_of: service.requester_of(&procedures.end_sessions_of)?,
            checked: service.requester_of(&procedures.checked)?,
        };
        let notifications = InteropNotifications {
            ticks: service.notification_of(&procedures.ticks)?,
        };

        Ok(Self {
            procedures,
            service,
            request,
            notifications,
        })
    }

    /// The requester of each procedure its server answers, by its name.
    #[must_use]
    pub const fn request(&self) -> &InteropRequesters {
        &self.request
    }

    /// The notification of each procedure that notifies, at the window its options gave, or unpaced.
    #[must_use]
    pub const fn notifications(&self) -> &InteropNotifications {
        &self.notifications
    }

    /// Registers the resolver of the command `clock`, which it answers.
    ///
    /// # Errors
    ///
    /// A [`ProgrammerError`](::bead::ProgrammerError) for a resolver registered already, or one its router refuses.
    pub fn on_clock<F, Fut>(&self, resolver: F) -> Result<(), ::bead::ProgrammerError>
    where
        F: Fn(
                ::bead::RequestProps<<::bead::JsonCodec as ::bead::PayloadCodec>::Value>,
                ::bead::Response<::bead::JsonCodec>,
            ) -> Fut
            + Send
            + Sync
            + 'static,
        Fut: ::core::future::Future<Output = Result<(), ::bead::ResolverError>> + Send + 'static,
    {
        self.service.on(
            &self.procedures.clock,
            ::std::sync::Arc::new(move |request, response| ::std::boxed::Box::pin(resolver(request, response))),
        )
    }
}

